#!/usr/bin/env python3
"""Fix <text> clipping in SVG files generated by R/ggplot2/svglite.

(冪等。何度掛けても結果は変わらない。)

rsvg-convert と Word の SVG レンダラは textLength/lengthAdjust を完全には
サポートしない。text-anchor='middle' + textLength のテキストは本来意図した幅より
広く描画され、clip-path 境界からはみ出す。本モジュールは:

1. 幅の狭い clip-path グループ内の <text> を、フルキャンバスの clip-path グループへ移す
2. 移動した text のみ: text-anchor='middle'/'end' を 'start' に変換し、x を意図した
   左端へ再計算、textLength/lengthAdjust を除去する
   (フルキャンバスグループ内の軸ラベル・タイトルは変更しない)

この操作は冪等。svglite はシングルクオート属性 (x='...') を出力するため、ここでも
シングルクオート前提でマッチする (手書き SVG でダブルクオート + textLength 無しの場合は
no-op になる)。

CLI:
    python3 fix_svg_clips.py figure.svg [figure2.svg ...]
モジュール:
    from fix_svg_clips import fix_svg_clips  # -> 修正した text 要素数を返す
"""

import re
import sys


def _transform_text(line):
    """Convert text-anchor/textLength to start-anchored at intended left edge.

    text-anchor='middle': new_x = x - textLength/2
    text-anchor='end':    new_x = x - textLength
    textLength と lengthAdjust 属性を除去する。
    transform= 付きの text (回転した軸タイトル等) はスキップする。
    Returns (transformed_line, was_changed).
    """
    s = line.strip()

    # transform 属性付き (回転ラベル等) はスキップ
    if "transform=" in s:
        return line, False

    tl_match = re.search(r"textLength='([^']+)'", s)
    if not tl_match:
        return line, False

    anchor_match = re.search(r"text-anchor='([^']+)'", s)
    anchor = anchor_match.group(1) if anchor_match else "start"

    if anchor == "start":
        return line, False

    x_match = re.search(r"\bx='([^']+)'", s)
    if not x_match:
        return line, False

    x = float(x_match.group(1))
    text_length = float(tl_match.group(1).replace("px", ""))

    # 開始位置を算出
    if anchor == "middle":
        new_x = x - text_length / 2
    elif anchor == "end":
        new_x = x - text_length
    else:
        return line, False

    new_line = line
    new_line = re.sub(r"\bx='[^']+'", f"x='{new_x:.2f}'", new_line)
    new_line = re.sub(r"text-anchor='[^']+'", "text-anchor='start'", new_line)
    new_line = re.sub(r"\s*textLength='[^']+'", "", new_line)
    new_line = re.sub(r"\s*lengthAdjust='[^']+'", "", new_line)

    return new_line, True


def fix_svg_clips(path):
    """Fix text clipping in an SVG file (in place).

    Returns the number of text elements moved/fixed (0 if no changes needed).
    冪等: 既に修正済み (狭い clip-path 内に <text> が無い) なら 0 を返し書き込まない。
    """
    with open(path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    text = "".join(lines)

    # viewBox 寸法を取得
    m = re.search(r"viewBox=['\"]([^'\"]+)['\"]", text)
    if not m:
        return 0
    vb = [float(x) for x in m.group(1).split()]
    vb_w, vb_h = vb[2], vb[3]

    # clipPath 定義を解析: id -> (x, y, width, height)
    clips = {}
    for m in re.finditer(
        r"<clipPath\s+id=['\"]([^'\"]+)['\"]>\s*"
        r"<rect\s+x=['\"]([^'\"]+)['\"]\s+y=['\"]([^'\"]+)['\"]\s+"
        r"width=['\"]([^'\"]+)['\"]\s+height=['\"]([^'\"]+)['\"]",
        text,
    ):
        clips[m.group(1)] = tuple(float(m.group(i)) for i in range(2, 6))

    if not clips:
        return 0

    # フルキャンバス vs 狭い clip-path に分類
    full_ids = {
        cid
        for cid, (x, y, w, h) in clips.items()
        if abs(w - vb_w) < 1 and abs(h - vb_h) < 1
    }
    narrow_ids = set(clips) - full_ids

    if not narrow_ids:
        return 0

    # clip-path グループのネストをスタックで追いながら行を走査
    result = []
    stack = []  # [(clip_id or None, is_narrow)]
    extracted = []
    last_full_close_idx = None

    for line in lines:
        s = line.strip()

        # 開始 <g ...>
        if re.match(r"<g[\s>]", s) or s == "<g>":
            gm = re.search(r"clip-path=['\"]url\(#([^)]+)\)['\"]", s)
            if gm:
                cid = gm.group(1)
                stack.append((cid, cid in narrow_ids))
            else:
                stack.append((None, False))
            result.append(line)
            continue

        # 終了 </g>
        if s == "</g>":
            if stack:
                cid, _ = stack.pop()
                if cid in full_ids:
                    last_full_close_idx = len(result)
            result.append(line)
            continue

        # 狭い clip-path グループ内なら <text> を抽出
        in_narrow = any(is_n for _, is_n in stack)
        if in_narrow and s.startswith("<text"):
            new_line, _ = _transform_text(line)
            extracted.append(new_line)
            continue

        result.append(line)

    if not extracted:
        return 0

    # 抽出した text を最後のフルキャンバスグループの直前 (</g> の前) に挿入
    if last_full_close_idx is not None:
        for tl in reversed(extracted):
            result.insert(last_full_close_idx, tl)
    else:
        for i in range(len(result) - 1, -1, -1):
            if result[i].strip() == "</g>":
                for tl in reversed(extracted):
                    result.insert(i, tl)
                break

    with open(path, "w", encoding="utf-8") as f:
        f.writelines(result)

    return len(extracted)


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <svg> [<svg> ...]", file=sys.stderr)
        sys.exit(1)

    total = 0
    for p in sys.argv[1:]:
        n = fix_svg_clips(p)
        if n:
            print(f"  {p}: fixed {n} text element(s)")
            total += n

    if total:
        print(f"Fixed {total} text element(s) total")
    else:
        print("No clip fixes needed (already clean or no narrow clip-paths).")


if __name__ == "__main__":
    main()
